"use client";

import "./autocomplete.css";

import type React from "react";

import { Autocomplete as BaseAutocomplete } from "@base-ui/react/autocomplete";
import { cn } from "tailwind-variants";

import { AutocompleteContext, useAutocompleteContext } from "./autocomplete.context";
import { autocompleteVariants, type AutocompleteVariants } from "./autocomplete.variants";

export type AutocompleteProps = AutocompleteVariants &
  React.ComponentProps<typeof BaseAutocomplete.Root>;

export function AutocompleteRoot({
  children,
  size,
  variant,
  ...props
}: AutocompleteProps) {
  const slots = autocompleteVariants({ size, variant });

  return (
    <AutocompleteContext.Provider value={{ slots }}>
      <BaseAutocomplete.Root {...props}>{children}</BaseAutocomplete.Root>
    </AutocompleteContext.Provider>
  );
}

export type AutocompleteInputProps = React.ComponentProps<typeof BaseAutocomplete.Input>;

export const AutocompleteInput = ({
  className,
  children,
  dangerouslySetInnerHTML,
  ...props
}: AutocompleteInputProps & { children?: React.ReactNode; dangerouslySetInnerHTML?: any }) => {
  const { slots } = useAutocompleteContext();
  const cleanProps = { ...props };
  delete (cleanProps as any).children;
  delete (cleanProps as any).dangerouslySetInnerHTML;
  return <BaseAutocomplete.Input className={cn(slots.input(), className)} {...cleanProps} />;
};

export type AutocompletePortalProps = React.ComponentProps<typeof BaseAutocomplete.Portal>;

export const AutocompletePortal = (props: AutocompletePortalProps) => {
  return <BaseAutocomplete.Portal {...props} />;
};

export type AutocompletePositionerProps = React.ComponentProps<typeof BaseAutocomplete.Positioner>;

export const AutocompletePositioner = ({
  className,
  sideOffset = 4,
  ...props
}: AutocompletePositionerProps) => {
  const { slots } = useAutocompleteContext();
  return (
    <BaseAutocomplete.Positioner
      className={cn(slots.positioner(), className)}
      sideOffset={sideOffset}
      {...props}
    />
  );
};

export type AutocompletePopupProps = React.ComponentProps<typeof BaseAutocomplete.Popup>;

export const AutocompletePopup = ({ className, ...props }: AutocompletePopupProps) => {
  const { slots } = useAutocompleteContext();
  return <BaseAutocomplete.Popup className={cn(slots.popup(), className)} {...props} />;
};

export type AutocompleteListProps = React.ComponentProps<typeof BaseAutocomplete.List>;

export function AutocompleteList({ className, ...props }: AutocompleteListProps) {
  const { slots } = useAutocompleteContext();
  return <BaseAutocomplete.List className={cn(slots.list(), className)} {...props} />;
}

export type AutocompleteItemProps = React.ComponentProps<typeof BaseAutocomplete.Item>;

export function AutocompleteItem({ className, ...props }: AutocompleteItemProps) {
  const { slots } = useAutocompleteContext();
  return <BaseAutocomplete.Item className={cn(slots.item(), className)} {...props} />;
}

export type AutocompleteEmptyProps = React.ComponentProps<typeof BaseAutocomplete.Empty>;

export const AutocompleteEmpty = ({ className, ...props }: AutocompleteEmptyProps) => {
  const { slots } = useAutocompleteContext();
  return <BaseAutocomplete.Empty className={cn(slots.empty(), className)} {...props} />;
};

export type AutocompleteStatusProps = React.ComponentProps<typeof BaseAutocomplete.Status>;

export const AutocompleteStatus = ({ className, ...props }: AutocompleteStatusProps) => {
  const { slots } = useAutocompleteContext();
  return <BaseAutocomplete.Status className={cn(slots.status(), className)} {...props} />;
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const autocompleteVariants = tv({
  slots: {
    root: "autocomplete",
    input: "autocomplete__input",
    portal: "autocomplete__portal",
    positioner: "autocomplete__positioner",
    popup: "autocomplete__popup",
    list: "autocomplete__list",
    item: "autocomplete__item",
    empty: "autocomplete__empty",
    status: "autocomplete__status",
    group: "autocomplete__group",
    groupLabel: "autocomplete__group-label",
  },
  variants: {
    variant: {
      default: {
        input: "autocomplete__input--default",
      },
      outline: {
        input: "autocomplete__input--outline",
      },
    },
    size: {
      sm: {
        input: "autocomplete__input--sm",
        item: "autocomplete__item--sm",
      },
      md: {
        input: "autocomplete__input--md",
        item: "autocomplete__item--md",
      },
      lg: {
        input: "autocomplete__input--lg",
        item: "autocomplete__item--lg",
      },
    },
  },
  defaultVariants: {
    variant: "default",
    size: "md",
  },
});

export type AutocompleteVariants = VariantProps<typeof autocompleteVariants>;

"use client";

import { createContext, useContext } from "react";

import { autocompleteVariants } from "./autocomplete.variants";

export type AutocompleteContext = {
  slots: ReturnType<typeof autocompleteVariants>;
};

export const AutocompleteContext = createContext<AutocompleteContext | null>(null);

export const useAutocompleteContext = () => {
  const context = useContext(AutocompleteContext);
  return context ?? { slots: autocompleteVariants() };
};

.autocomplete__input {
  @apply flex w-full rounded-md border border-input bg-background px-3 py-2 text-sm text-foreground shadow-xs transition-colors placeholder:text-muted-foreground focus-visible:outline-2 focus-visible:outline-ring disabled:cursor-not-allowed disabled:opacity-50;
}

.autocomplete__input--sm {
  @apply h-8 text-xs px-2.5;
}

.autocomplete__input--md {
  @apply h-9 text-sm px-3;
}

.autocomplete__input--lg {
  @apply h-10 text-base px-3.5;
}

.autocomplete__positioner {
  @apply outline-none z-50;
}

.autocomplete__popup {
  @apply w-[var(--anchor-width)] max-w-[var(--available-width)] overflow-hidden rounded-md border border-border bg-popover text-popover-foreground shadow-md transition-all duration-100 ease-out data-ending-style:opacity-0 data-starting-style:opacity-0;
}

.autocomplete__list {
  @apply outline-none overflow-y-auto scroll-py-1 p-1 overscroll-contain max-h-[min(20rem,var(--available-height))] data-empty:p-0;
}

.autocomplete__item {
  @apply relative flex cursor-default select-none items-center rounded-sm px-2 py-1.5 text-sm text-foreground outline-none transition-colors data-highlighted:bg-accent data-highlighted:text-accent-foreground data-disabled:pointer-events-none data-disabled:opacity-50;
}

.autocomplete__item--sm {
  @apply px-2 py-1 text-xs;
}

.autocomplete__item--md {
  @apply px-2.5 py-1.5 text-sm;
}

.autocomplete__item--lg {
  @apply px-3 py-2 text-base;
}

.autocomplete__empty {
  @apply p-3 text-center text-sm text-muted-foreground;
}

.autocomplete__status {
  @apply p-2 text-xs text-muted-foreground;
}

.autocomplete__group-label {
  @apply px-2 py-1.5 text-xs font-semibold text-muted-foreground;
}

import {
  AutocompleteEmpty,
  AutocompleteInput,
  AutocompleteItem,
  AutocompleteList,
  AutocompletePopup,
  AutocompletePortal,
  AutocompletePositioner,
  AutocompleteRoot,
  AutocompleteStatus,
} from "./autocomplete";

export const Autocomplete = {
  Empty: AutocompleteEmpty,
  Input: AutocompleteInput,
  Item: AutocompleteItem,
  List: AutocompleteList,
  Popup: AutocompletePopup,
  Portal: AutocompletePortal,
  Positioner: AutocompletePositioner,
  Root: AutocompleteRoot,
  Status: AutocompleteStatus,
};

export {
  AutocompleteEmpty,
  AutocompleteInput,
  AutocompleteItem,
  AutocompleteList,
  AutocompletePopup,
  AutocompletePortal,
  AutocompletePositioner,
  AutocompleteRoot,
  AutocompleteStatus,
};

export type {
  AutocompleteEmptyProps,
  AutocompleteInputProps,
  AutocompleteItemProps,
  AutocompleteListProps,
  AutocompletePopupProps,
  AutocompletePortalProps,
  AutocompletePositionerProps,
  AutocompleteProps,
  AutocompleteStatusProps,
} from "./autocomplete";
export { AutocompleteContext, useAutocompleteContext } from "./autocomplete.context";
export { type AutocompleteVariants, autocompleteVariants } from "./autocomplete.variants";
